import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.C-si7TFR.js";const c=JSON.parse('{"title":"表单与人工协作","description":"","frontmatter":{"title":"表单与人工协作"},"headers":[],"relativePath":"zh/guide/forms.md","filePath":"zh/guide/forms.md"}'),i={name:"zh/guide/forms.md"};function o(d,t,h,n,s,_){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="表单与人工协作" tabindex="-1">表单与人工协作 <a class="header-anchor" href="#表单与人工协作" aria-label="Permalink to &quot;表单与人工协作&quot;">​</a></h1><p>表单负责采集输入，表单任务与审批让流程等待人工处理。三者可以组合，但不是同一个节点。</p><h2 id="设计表单" tabindex="-1">设计表单 <a class="header-anchor" href="#设计表单" aria-label="Permalink to &quot;设计表单&quot;">​</a></h2><ol><li>在<strong>表单</strong>页面选择<strong>新建</strong>，使用设计器添加字段。</li><li>配置字段标题、输入方式与必填规则，保存表单。</li><li>用测试数据检查字段、校验和提交内容，不要在示例中填写真实敏感信息。</li></ol><h2 id="三种使用方式" tabindex="-1">三种使用方式 <a class="header-anchor" href="#三种使用方式" aria-label="Permalink to &quot;三种使用方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>行为</th></tr></thead><tbody><tr><td><a href="./../trigger_form.html">表单触发器</a></td><td>用户提交表单，启动关联工作流</td></tr><tr><td><a href="./../form_task.html">表单任务</a></td><td>流程运行到该节点，为成员创建待填写任务，按条件继续</td></tr><tr><td><a href="./../approval.html">审批</a></td><td>流程等待成员审批，按通过、驳回或超时路径继续</td></tr></tbody></table><h2 id="示例-采集-→-处理-→-人工确认" tabindex="-1">示例：采集 → 处理 → 人工确认 <a class="header-anchor" href="#示例-采集-→-处理-→-人工确认" aria-label="Permalink to &quot;示例：采集 → 处理 → 人工确认&quot;">​</a></h2><p>以下示例只使用表单、数据表和工作流，不依赖业务页面发布。</p><ol><li>创建一个“申请记录”数据表，包含申请内容和处理状态等字段。</li><li>创建“申请提交”表单，收集申请内容。</li><li>创建工作流，添加表单触发器并选择该表单，按需配置允许提交的成员。</li><li>添加<a href="./../data_table_insert.html">数据表插入</a>，将申请内容映射到申请记录表，初始状态设为待处理。</li><li>如需补充信息，添加表单任务并选择已创建的表单和成员；如需批准，改用审批节点。</li><li>在后续分支根据任务或审批结果更新状态，并配置明确的输出。</li><li>保存后提交一条测试表单，在执行记录中检查触发数据；有任务时到<strong>用户任务</strong>处理待办。</li><li>最后检查数据表记录和流程输出，确认整条路径完成。</li></ol><p>表单任务支持按或签／会签等实际配置判断后续流转，具体条件以节点说明为准。不要把提交成功等同于审批通过或流程全部完成。</p><h2 id="访问与隐私" tabindex="-1">访问与隐私 <a class="header-anchor" href="#访问与隐私" aria-label="Permalink to &quot;访问与隐私&quot;">​</a></h2><p>表单触发器的成员配置决定允许提交的范围；公开提交地址前确认身份验证与访问边界。表单内容会进入执行记录和后续工具，分享截图、日志和链接前检查敏感信息。</p>',12)])])}const f=a(i,[["render",o]]);export{c as __pageData,f as default};
